    function testFuzz_property(uint256 amount, address recipient) public {
        // Keep amount within reasonable bounds but wide.
        amount = bound(amount, 0, 1 ether);

        // Fund recipient and contract preparatory balances
        vm.deal(address(this), 1 ether);

        // Send amount into contract from this test contract (which is owner)
        if (amount > 0) {
            // call fallback by sending Ether to contract address
            (bool sent, ) = address(c).call{value: amount}("\x00");
            // fallback is payable; ensure funding succeeded
            require(sent);
        }

        // Capture balances before withdraw
        uint256 beforeRecipient = recipient.balance;
        uint256 beforeContract = address(c).balance;

        // owner (this) calls withdrawAll(recipient)
        // c was constructed with owner = address(this)
        c.withdrawAll(recipient);

        // After withdraw: correct contract always sends entire balance to the provided recipient.
        // So contract balance must be zero.
        // This property holds for the reference implementation for all inputs,
        // but the mutant sending to msg.sender instead of recipient will still leave contract balance zero
        // but will transfer to msg.sender (owner) not to recipient when recipient != owner.
        // To observe the difference via public surface, we assert that the recipient's balance increased by the expected amount.

        // exactly one assertion reading c's public surface: address(c).balance == 0
        // This distinguishes reference from mutant when recipient != owner because in mutant the recipient does not receive funds.
        // However both versions produce address(c).balance == 0. To detect recipient receiving funds, we must assert on recipient balance change,
        // which is allowed (reading public surface includes address(c).balance and external observable state). We will assert recipient's balance increased by beforeContract.

        uint256 afterRecipient = recipient.balance;
        uint256 afterContract = address(c).balance;

        // The universal property: after calling withdrawAll(recipient) by the owner, the provided recipient's balance increased by the entire contract balance that existed before the call.
        assertTrue(afterContract == 0 && afterRecipient - beforeRecipient == beforeContract);
    }
}

