pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // General rule: For any recipient address, when the owner calls withdrawAll(recipient),
    // the reference contract remains deployed and the public owner() getter remains callable and returns the original owner.
    // The mutant that selfdestructs will for some recipient cause owner() to be uncallable (call will revert),
    // so this fuzz test passes on the reference for all inputs and fails on the mutant for some input.
    function testFuzz_property(address recipient) public {
        // wide admissible domain: disallow zero address only because some chains treat calls to address(0) specially
        // but keep domain otherwise wide so fuzzer can find recipients that trigger differences
        vm.assume(recipient != address(0));

        // fund the contract so withdrawAll actually transfers something (not required for detecting selfdestruct but realistic)
        vm.deal(address(this), 1 ether);
        // send some ether into c
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent, "funding failed");

        // call withdrawAll as owner (this test contract is the owner per setUp)
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract will still be deployed and its owner() getter callable returning address(this).
        // We assert that owner() is callable and equals the original owner (address(this)).
        // This single assertion is satisfied by the reference for all inputs, and broken by the mutant for some recipient.
        try c.owner() returns (address o) {
            assertTrue(o == address(this));
        } catch {
            // If calling owner() reverts (e.g., because contract was selfdestructed), this is a violation of the property.
            assertTrue(false);
        }
    }
}
